    always @(posedge clk) begin
        if (rst) begin
            valid_out <= 1'b0;
            i_out     <= 8'sd0;
            q_out     <= 8'sd0;
        end else begin
            valid_out <= valid_in;                            // timing untouched
            i_out     <= sat8(i_rot + noise3(lfsr[2:0]));
            q_out     <= sat8(q_rot + noise3(lfsr[5:3]));
