                            ? DEFAULT_SEED : seed;

    always @(posedge clk) begin
        if (rst) lfsr <= seed_eff;
        else     lfsr <= {lfsr[30:0], fb};   // advances every cycle (deterministic)
    end

    //---------------- noise: +/-3 LSB, two independent streams ----------
    function signed [8:0] noise3(input [2:0] s);
        case (s)
            3'd0:    noise3 = -9'sd3;
            3'd1:    noise3 = -9'sd2;
            3'd2:    noise3 = -9'sd1;
            3'd3:    noise3 =  9'sd0;
            3'd4:    noise3 =  9'sd1;
            3'd5:    noise3 =  9'sd2;
            default: noise3 =  9'sd3;   // 3'd6, 3'd7
        endcase
    endfunction

    //---------------- rotation: 9-bit signed intermediate ----------------
    wire signed [8:0] i_ext = i_in;
    wire signed [8:0] q_ext = q_in;
    wire signed [8:0] i_rot = i_ext - (q_ext >>> 4);
    wire signed [8:0] q_rot = q_ext + (i_ext >>> 4);

    //---------------- saturate to signed 8-bit ---------------------------
    function signed [7:0] sat8(input signed [8:0] v);
        sat8 = (v >  9'sd127) ?  8'sd127 :
               (v < -9'sd128) ? -8'sd128 : v[7:0];
    endfunction

    //---------------- registered output ----------------------------------
    always @(posedge clk) begin
        if (rst) begin
            valid_out <= 1'b0;
            i_out     <= 8'sd0;
            q_out     <= 8'sd0;
        end else if (valid_in) begin
            valid_out <= 1'b1;
            i_out     <= sat8(i_rot + noise3(lfsr[2:0]));
            q_out     <= sat8(q_rot + noise3(lfsr[5:3]));
        end else begin
            valid_out <= 1'b0;
            i_out     <= 8'sd0;
            q_out     <= 8'sd0;
        end
    end

endmodule

// ====================================================
// cell=W-10_ch_idle_zero  file=qpsk_demodulator.sv
// ====================================================
`timescale 1ns/1ps
//------------------------------------------------------------
// qpsk_demodulator.sv
// QPSK demodulator: zero-threshold slicer on signed (I,Q)
// Polarity matched to qpsk_modulator constellation table:
//   i_in < 0 -> I_bit (bits[1]) = 1, else 0
//   q_in < 0 -> Q_bit (bits[0]) = 1, else 0
// 1-cycle latency: outputs registered, valid_out <= valid_in
//------------------------------------------------------------
module qpsk_demodulator_W_10_ch_idle_zero (
    input  wire              clk,
    input  wire              rst,
    input  wire              valid_in,
    input  wire signed [7:0] i_in,
    input  wire signed [7:0] q_in,
    output reg               valid_out,
    output reg  [1:0]        bits
);

    always @(posedge clk) begin
        if (rst) begin
            valid_out <= 1'b0;
            bits      <= 2'b00;
        end else begin
            valid_out <= valid_in;
            bits[1]   <= (i_in < 8'sd0) ? 1'b1 : 1'b0;
            bits[0]   <= (q_in < 8'sd0) ? 1'b1 : 1'b0;
        end
    end

endmodule

